if($error===''){$imagen=$nueva!==null?$nueva:$producto['imagen'];$up=$db->prepare('UPDATE productos SET nombre=?,descripcion=?,precio=?,imagen=?,stock=?,categoria_id=? WHERE id=?');$up->bind_param('ssdsiii',$nombre,$descripcion,$precio,$imagen,$stock,$categoria_id,$id);if($up->execute()){$up->close();if($nueva!==null)borrar_imagen($producto['imagen']);$db->close();header('Location: mostrar_datos.php?msg='.urlencode('Producto actualizado'));exit;}$error='No se pudo actualizar: '.$up->error;borrar_imagen($nueva);$up->close();}}
